import { Box, TextField, Typography } from "@mui/material";

export default function Login() {
    return (
        <Box
            display="flex"
            justifyContent="center"
            alignItems="center"
            height="100vh"
            width="100%"
            style={{ position: "relative" }}
        >
            <Box
                bgcolor="rgba(255, 255, 255, 0.8)"
                borderRadius="8px"
                padding="55px"
                boxShadow="0 4px 6px rgba(0, 0, 0, 0.1)"
                textAlign="center"
                width="15%"
                style={{
                    backdropFilter: "blur(10px)",
                    WebkitBackdropFilter: "blur(10px)"
                }}
            >
                <Typography fontWeight="bold" fontSize="25px" mb="30px">VSpaceにログイン</Typography>
                <TextField id="email" label="Email" variant="outlined" fullWidth style={{ marginBottom: "15px" }} />
                <TextField id="password" label="Password" variant="outlined" fullWidth style={{ marginBottom: "30px" }} />
            </Box>
        </Box>
    )
}
